insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('0ba2ebc5-dcdb-4962-a1ef-128202d2f2e6', '3d980227-6055-4ad2-9b4b-60fe6e501d39', $$uit Nieuwsvoornop.nl (december 2014): daling papieren krantenabonnementen, sinds 2012 keuze tussen papierplus- en digitaal abonnement$$,
   $$economie-havo-2019-i-papier-hier-context1.png$$,
   $$uit Nieuwsvoornop.nl, december 2014: Het aantal papieren krantenabonnementen is in de periode 2005-2012 enorm gedaald. Dat is onder andere het gevolg van een toenemend aantal alternatieve nieuwsbronnen zoals televisie, internet en gratis papieren kranten. De compensatie voor deze daling wordt door de dagbladaanbieders voornamelijk gezocht in het aanbieden van digitale kranten. Hierdoor kan de lezer sinds 2012 bij veel dagbladaanbieders kiezen tussen twee typen abonnementen:
− een papierplus-abonnement (papieren + digitale krant)
− een digitaal abonnement (alleen digitale krant).$$, 'inline'),
  ('b44f7dc4-d9dc-43ea-8c1e-9b67c31debe0', '3d980227-6055-4ad2-9b4b-60fe6e501d39', $$gezamenlijk marktaandeel van de drie grootste dagbladaanbieders veranderde in 2005-2012$$,
   $$economie-havo-2019-i-papier-hier-context2.png$$,
   $$In de periode 2005-2012 zagen de drie grootste dagbladaanbieders, het Hollands Dagblad, de 7Provinciën en de Krant van Vandaag, hun gezamenlijk marktaandeel veranderen.$$, 'inline'),
  ('6282b9b4-290f-40ec-b00b-e88d02c199e0', '3d980227-6055-4ad2-9b4b-60fe6e501d39', $$Krant van Vandaag: papierplus-abonnement duurder, digitaal gelijk; twee uitspraken van een marketingmedewerker$$,
   $$economie-havo-2019-i-papier-hier-context3.png$$,
   $$Vanaf 2012 verkoopt de Krant van Vandaag zowel een papierplus- abonnement als een digitaal abonnement. Door stijgende papierprijzen en toenemende distributiekosten is het papierplus-abonnement in de periode 2012-2014 duurder geworden (zie bron 2), terwijl de prijs van een digitaal abonnement gelijk is gebleven (zie bron 3). Een marketingmedewerker van de Krant van Vandaag doet de volgende uitspraken:
1 “De vraaglijn van een digitaal abonnement is in de periode 2012-2014 verschoven, omdat de prijs van een papierplus-abonnement is gestegen.”
2 “Hierdoor is het consumentensurplus op de markt van digitale abonnementen toegenomen.”$$, 'inline'),
  ('8d695778-040e-4096-a4e1-a5713dbae9ff', '3d980227-6055-4ad2-9b4b-60fe6e501d39', $$bron 1: marktaandelen op basis van de omzet van de drie grootste dagbladaanbieders (2005-2012)$$,
   $$economie-havo-2019-i-papier-hier-context4.png$$,
   $$bron 1 marktaandelen op basis van de omzet van de drie grootste dagbladaanbieders van papieren krantenabonnementen
lijngrafiek: marktaandeel op basis van omzet in procenten (20-90) tegen jaren (2005-2012)
drie grootste dagbladen (Hollands Dagblad, 7Provinciën en Krant van Vandaag): 75 in 2005, 83 in 2012
twee grootste dagbladen (Hollands Dagblad en 7Provinciën): 55 in 2005, 60 in 2012
grootste dagblad (Hollands Dagblad): 34 in 2005, 38 in 2012$$, 'inline'),
  ('82814f12-922c-41f8-bb72-0e47206a4cd0', '3d980227-6055-4ad2-9b4b-60fe6e501d39', $$bron 2: gegevens van het papierplus-jaarabonnement van de Krant van Vandaag (2012-2014)$$,
